ST.xhtml:p:
IF g_nFAxisControlType = 0 THEN
  g_bFocusDone := TRUE;
  RETURN;
END_IF;

   (*变焦轴类型 0 :手动头关闭 1 ：F050 2 轴控制BM109,110,111,114S,115,BM06K 3: 普雷斯特 4:BM11X 5:BS12K,BS06K总线 5:BS12K  6:BM115E 7.BM116E 8.BM111E 9.BM114E 
  10.BS04K,BS06K,BS08K,BS12K,BS20K,BS30K模拟量 11:BS04K总线 12.BS04KE,BS06KE,BS08KE,BS12KE,BS15KE,BS20KE,BS25KE,BS30KE*)
CASE g_nFAxisControlType OF
  1:  
    IF g_dZoomPosition <> dLastZoomPosition THEN(*调焦坐标变化时，触发模拟量调焦*)
      g_bAnalogEnable := TRUE;      
      g_dAnalogPosition := g_dZoomPosition;        
    END_IF;
    g_bFocusDone := TRUE;
    FBFAxisAnalogControl();
    g_nFAxisControl := 1;
  2:  
    IF g_boFHomeDone THEN         
      g_dAnalogPosition := g_dZoomPosition; 
      g_bFAbsoluteEnable := g_bFocusEnable; 
    END_IF;
    g_nFAxisControl := 2;
  3:
	g_bAnalogEnable := g_bFocusEnable;      
    g_dAnalogPosition := g_dZoomPosition; 
    FBPresterAutoFocusControl(); 
    g_nFAxisControl := 1;
  4: 
    g_dAnalogPosition := g_dZoomPosition; 
    g_bFBM11XEnable := g_bFocusEnable;   (*去BM11X控制调焦*)   
    FBFAxisBM11XCtl();
    g_nFAxisControl := 3;
  5: 
    g_dAnalogPosition := g_dZoomPosition; 
    g_bFBS12KEnable := g_bFocusEnable;   (*去BS12K控制调焦*)   
    FBFAxisBS12KCtl(); 
    g_nFAxisControl := 3;
  6:
    g_dAnalogPosition := g_dZoomPosition; 
    g_bFBM115EEnable := g_bFocusEnable;   (*去BM115E控制调焦*)    
    FBFAxisBM115ECtl(); 
    g_nFAxisControl := 3;
  7:(*BM116E*)
    g_dAnalogPosition := g_dZoomPosition;
    g_nFAxisControl := 3;
  8: 
    g_dAnalogPosition := g_dZoomPosition; 
    g_bFBM111EEnable := g_bFocusEnable;   (*去BM111E控制调焦*)   
    FBFAxisBM111ECtl(); 
    g_nFAxisControl := 3;
  9:
    g_dAnalogPosition := g_dZoomPosition; 
    g_bFBM114EEnable := g_bFocusEnable;   (*去BM114E控制调焦*)   
    FBFAxisBM114ECtl();
    g_nFAxisControl := 3;
  10:
    g_bAnalogEnable := g_bFocusEnable; 
    g_dAnalogPosition := g_dZoomPosition;   
    FBFAxisBS06K();
    g_nFAxisControl := 1;
  11: (*BS04K没有聚焦镜温度，需屏蔽*)
    g_dAnalogPosition := g_dZoomPosition; 
    g_bBS04KEnable := g_bFocusEnable;   
    FBFAxisBS04K();
    g_nFAxisControl := 3;
  12:
    FBFAxisBS12KE();
    g_nFAxisControl := 3;
  13,15:  
    IF g_boFHomeDone THEN         
      g_dAnalogPosition := g_dZoomPosition; 
      g_bFAbsoluteEnable := g_bFocusEnable;   (*去轴控绝对运动调焦*)   
    END_IF;
    FBBS03CAT();
    g_nFAxisControl := 2;
  14:  
    IF g_boFHomeDone THEN         
      g_dAnalogPosition := g_dZoomPosition; 
      g_bFAbsoluteEnable := g_bFocusEnable;   (*去轴控绝对运动调焦*)   
    END_IF;
    FBBS06CAT();
    g_nFAxisControl := 2;
END_CASE;

dLastZoomPosition := g_dZoomPosition;
